import test from 'node:test';import assert from 'node:assert/strict';import {vectorLicenseLabel} from './vector-license.js';import official from './official-vector-native.fixture.json' with {type:'json'};import overture from './overture-native.fixture.json' with {type:'json'};
test('actual Microsoft and Overture source licences retain their distinct labels',()=>{assert.equal(vectorLicenseLabel(official[0]),'CDLA Permissive 2.0');assert.equal(vectorLicenseLabel(official[1]),'ODbL');assert.equal(vectorLicenseLabel(overture.asset),'ODbL');assert.equal(vectorLicenseLabel({licenseUrl:'https://publisher.example/terms'}),'Publisher terms of use');});
